import React, { useState } from 'react';
import AdoptionCard from '../AdoptionCard/AdoptionCard';
import '../../styles/AdoptionPostForm.css';
const PostAnimalForm = () => {
  // State to store form data
  const [formData, setFormData] = useState({
    animalName: '',
    animalPlace: '',
    animalGender: '',
    animalAge: '',
    animalType: '',
    additionalNotes: '',
    animalImage: null,
  });

  // State to store the posted card
  const [postedAnimal, setPostedAnimal] = useState(null);

  // Handle form input change
  const handleInputChange = (e) => {
    const { name, value, type, files } = e.target;
    setFormData((prevData) => ({
      ...prevData,
      [name]: type === 'file' ? files[0] : value,
    }));
  };

  // Handle form submission
  const handleSubmit = (e) => {
    e.preventDefault();
    const { animalName, animalPlace, animalGender, animalAge, animalType, animalImage } = formData;

    if (animalName && animalPlace && animalGender && animalAge && animalType && animalImage) {
      setPostedAnimal({
        name: animalName,
        place: animalPlace,
        details: `${animalGender}, ${animalAge} years old, ${animalType}`,
        image: URL.createObjectURL(animalImage), // Convert image file to URL
      });
    } else {
      alert('Please fill all required fields.');
    }
  };

  return (
    <div>
      <h2>Post an Animal for Adoption</h2>
      <form onSubmit={handleSubmit}>
        <label htmlFor="animal-name">Animal Name:</label>
        <input
          type="text"
          id="animal-name"
          name="animalName"
          value={formData.animalName}
          onChange={handleInputChange}
          placeholder="Enter the animal's name"
          required
        />

        <label htmlFor="animal-place">Animal Place:</label>
        <input
          type="text"
          id="animal-place"
          name="animalPlace"
          value={formData.animalPlace}
          onChange={handleInputChange}
          placeholder="Enter the animal's place"
          required
        />

        <label htmlFor="animal-gender">Animal Gender:</label>
        <select
          id="animal-gender"
          name="animalGender"
          value={formData.animalGender}
          onChange={handleInputChange}
          required
        >
          <option value="">Select the gender</option>
          <option value="Female">Female</option>
          <option value="Male">Male</option>
        </select>

        <label htmlFor="animal-age">Animal Age:</label>
        <input
          type="number"
          id="animal-age"
          name="animalAge"
          value={formData.animalAge}
          onChange={handleInputChange}
          placeholder="Enter the animal's age"
          required
        />

        <label htmlFor="animal-type">Animal Type:</label>
        <select
          id="animal-type"
          name="animalType"
          value={formData.animalType}
          onChange={handleInputChange}
          required
        >
          <option value="">Select the type</option>
          <option value="Cat">Cat</option>
          <option value="Dog">Dog</option>
          <option value="Rabbit">Rabbit</option>
          <option value="Other">Other</option>
        </select>

        <label htmlFor="additional-notes">Additional Notes:</label>
        <textarea
          id="additional-notes"
          name="additionalNotes"
          value={formData.additionalNotes}
          onChange={handleInputChange}
          placeholder="Enter any additional notes (including health conditions if any)"
          rows="4"
        ></textarea>

        <label htmlFor="animal-image">Upload Animal Picture:</label>
        <input
          type="file"
          id="animal-image"
          name="animalImage"
          accept="image/*"
          onChange={handleInputChange}
          required
        />

        <button type="submit">Submit</button>
      </form>

      {postedAnimal && (
        <div>
          <h3>Animal Posted:</h3>
          <AdoptionCard {...postedAnimal} />
        </div>
      )}
    </div>
  );
};

export default PostAnimalForm;
